mapper.select:
SELECT *
FROM
`inspection`.inspection_cash_bond  a
WHERE 1=1

    AND a.`TASK_ID` = #{params.TASK_ID}


    AND a.`SHEET_ID` = #{params.SHEET_ID}

mapper.update:
UPDATE `inspection`.inspection_cash_bond a
SET
SHEET_ID=#{params.SHEET_ID}
,TASK_TYPE_DSCR=#{params.TASK_TYPE_DSCR}
,TASK_ID=#{params.TASK_ID}
,FILLING_DATE=#{params.FILLING_DATE}
,OUTSIDE_SUBJECT=#{params.OUTSIDE_SUBJECT}
,BALANCE_ALL=#{params.BALANCE_ALL}
,BALANCE=#{params.BALANCE}
,REASON=#{params.REASON}
,OPERATOR_GUOKU=#{params.OPERATOR_GUOKU}
,OPERATOR=#{params.OPERATOR}
,LARDER=#{params.LARDER}
,RUMMAGER=#{params.RUMMAGER}
,ATTACHMENT_NAME=#{params.ATTACHMENT_NAME}
,PAPER_ATTACHMENT=#{params.PAPER_ATTACHMENT}
,PRINT_ATTACHMENT=#{params.PRINT_ATTACHMENT}
,INSPECTED=#{params.INSPECTED}
,ADD_USERID=#{params.ADD_USERID}
,ADD_DATE=#{params.ADD_DATE}
,MODIFY_USERID=#{params.MODIFY_USERID}
,MODIFY_DATE=#{params.MODIFY_DATE}
WHERE 1=1

    AND a.`TASK_ID` = #{params.TASK_ID}


    AND a.`SHEET_ID` = #{params.SHEET_ID}

mapper.select:
SELECT a.* ,c.name AS NAME, CONCAT(d.`guoku_dscr`,'已兑付国家债券现场检查账实核对表') AS SHEET_NAME, d.`guoku_dscr` as INSPECTED_DSCR FROM `inspection`.`inspection_cash_bond` a LEFT JOIN dmcode.`cm_guoku_dimnsn` d ON a.INSPECTED=d.`guoku_id` LEFT JOIN inspection.inspection_sysuser_talentpool_relation b ON b.SYS_USERID = a.ADD_USERID LEFT JOIN inspection.cm_guoku_talentpool c ON b.TALENTPOOL_ID = c.UUID where 1=1
AND a.TASK_ID = #{params.TASK_ID}
order by ADD_DATE,a.MODIFY_DATE desc

mapper.delete:
delete from `inspection`.`inspection_cash_bond` where 1=1

    AND TASK_ID = #{params.TASK_ID}


    AND INSPECTED = #{params.INSPECTED}

mapper.select:
SELECT * FROM    `inspection`.`inspection_data_check` a
 WHERE 1=1

      AND TASK_ID = #{params.TASK_ID}


      AND INSPECTED = #{params.INSPECTED}
